	@Test
	void predicateSweepCoversOverlayReplacementDeletionAndHistoricalSnapshot() throws Exception {
		long baseRevision = tripleStore.getDataRevision();
		long p3 = uri(103);
		long s3 = uri(3);
		long o3 = uri(203);
		long graph = uri(301);
		long replacement = uri(204);

		tripleStore.startTransaction();
		tripleStore.storeTriple(s3, p3, o3, graph, true);
		tripleStore.removeTriplesByContext(S1, P1, O1, 0, true, removed -> {
		});
		tripleStore.storeTriple(S1, P1, replacement, 0, true);
		tripleStore.removeTriplesByContext(S1, P2, O1, 0, true, removed -> {
		});
		tripleStore.commit();
		store.applyCommitted(tripleStore.drainDirectAdjacencyCommitDelta());
		store.pauseApplierForTest(false);

		try (LmdbAdjacencyReadView historical = store.acquire(baseRevision);
				LmdbAdjacencyReadView latest = store.acquire(tripleStore.getDataRevision())) {
			assertThat(historical.isExact()).isTrue();
			assertThat(latest.isExact()).isTrue();
			assertThat(rows(store.tryOpen(historical, null, -1, -1, -1, -1, true)))
					.containsExactlyInAnyOrder(
							List.of(S1, P1, O1, 0L),
							List.of(S1, P2, O1, 0L),
							List.of(S2, P1, O2, 0L));
			assertThat(rows(store.tryOpen(latest, null, -1, -1, -1, -1, true)))
					.as("the general predicate sweep resolves the complete retained update history")
					.containsExactlyInAnyOrder(
							List.of(S1, P1, replacement, 0L),
							List.of(S2, P1, O2, 0L),
							List.of(s3, p3, o3, graph));
		}
	}

	@Test
	void admittedUniversalIteratorsKeepTheirRetainedSnapshotWhenAWriterBecomesDirty() throws Exception {
		List<List<Long>> expected = List.of(
				List.of(S1, P1, O1, 0L),
				List.of(S1, P2, O1, 0L),
				List.of(S2, P1, O2, 0L));
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			for (StatementOrder order : new StatementOrder[] { null, StatementOrder.S, StatementOrder.O }) {
				RecordIterator admitted = order == null
						? store.tryOpen(view, null, -1, -1, -1, -1, true)
						: store.tryOpenOrdered(view, null, order, -1, -1, -1, -1, true);
				store.storeTxnStartedFlag().set(true);
				store.storeTxnDirtyFlag().set(true);
				try {
					assertThat(rows(admitted))
							.as("an admitted %s universal iterator owns its immutable read view", order)
							.containsExactlyInAnyOrderElementsOf(expected);
					assertThat(store.tryOpen(view, null, -1, -1, -1, -1, true))
							.as("a new universal iterator must still honor the dirty-writer gate")
							.isNull();
				} finally {
					store.storeTxnDirtyFlag().set(false);
					store.storeTxnStartedFlag().set(false);
				}
			}
		}
	}

	@Test
	void exactFullOffersEveryBindingMaskInEveryPrimaryOrder() throws Exception {
		List<List<Long>> all = List.of(
				List.of(S1, P1, O1, 0L),
				List.of(S1, P2, O1, 0L),
				List.of(S2, P1, O2, 0L));
		try (LmdbAdjacencyReadView view = store.acquire(tripleStore.getDataRevision())) {
			for (int mask = 0; mask < 16; mask++) {
				long subject = (mask & 1) == 0 ? -1L : S1;
				long predicate = (mask & 2) == 0 ? -1L : P1;
				long object = (mask & 4) == 0 ? -1L : O1;
				long context = (mask & 8) == 0 ? -1L : 0L;
				List<List<Long>> expected = matchingRows(all, subject, predicate, object, context);
				for (StatementOrder order : StatementOrder.values()) {
					List<List<Long>> ordered = rows(store.tryOpenOrdered(view, null, order, subject, predicate, object,
							context, true));
					assertThat(ordered)
							.as("binding mask %s in %s order", Integer.toBinaryString(mask), order)
							.containsExactlyInAnyOrderElementsOf(expected);
					int component = switch (order) {
					case S -> TripleIndex.SUBJ_IDX;
					case P -> TripleIndex.PRED_IDX;
					case O -> TripleIndex.OBJ_IDX;
					case C -> TripleIndex.CONTEXT_IDX;
					};
					for (int row = 1; row < ordered.size(); row++) {
						assertThat(Long.compareUnsigned(ordered.get(row - 1).get(component),
								ordered.get(row).get(component)))
										.as("mask %s, %s order at row %s", Integer.toBinaryString(mask), order, row)
										.isLessThanOrEqualTo(0);
					}
				}
			}
		}
	}

