			for (int mask = 0; mask < 16; mask++) {
				long subject = (mask & 1) == 0 ? -1L : S1;
				long predicate = (mask & 2) == 0 ? -1L : P1;
				long object = (mask & 4) == 0 ? -1L : O1;
				long context = (mask & 8) == 0 ? -1L : 0L;
				assertThat(rows(store.tryOpenRange(view, complete, subject, predicate, object, context, true)))
						.as("native range binding mask %s", Integer.toBinaryString(mask))
						.containsExactlyElementsOf(matchingRows(all, subject, predicate, object, context));
			}
