	private static List<List<Long>> matchingRows(List<List<Long>> all, long subject, long predicate, long object,
			long context) {
		return all.stream()
				.filter(row -> subject < 0 || row.get(0) == subject)
				.filter(row -> predicate < 0 || row.get(1) == predicate)
				.filter(row -> object < 0 || row.get(2) == object)
				.filter(row -> context < 0 || row.get(3) == context)
				.toList();
	}

	private static List<List<Long>> rows(RecordIterator iterator) {
		assertThat(iterator).as("the direct provider must offer a candidate").isNotNull();
		List<List<Long>> rows = new ArrayList<>();
		try {
			long[] quad;
			while ((quad = iterator.next()) != null) {
				rows.add(List.of(quad[TripleIndex.SUBJ_IDX], quad[TripleIndex.PRED_IDX],
						quad[TripleIndex.OBJ_IDX], Math.max(0L, quad[TripleIndex.CONTEXT_IDX])));
			}
		} finally {
			iterator.close();
		}
		return rows;
	}
